import{_ as o,o as e,c as l,a2 as r}from"./chunks/framework.CiKk3sJz.js";const m=JSON.parse('{"title":"漫画 · 第 35 话 滚动吸附：松手即停稳","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.35-scroll-snap.md","filePath":"comics/css/EP.35-scroll-snap.md","lastUpdated":1792579602000}'),s={name:"comics/css/EP.35-scroll-snap.md"};function c(t,a,d,n,i,p){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="漫画-·-第-35-话-滚动吸附-松手即停稳" tabindex="-1">漫画 · 第 35 话 滚动吸附：松手即停稳 <a class="header-anchor" href="#漫画-·-第-35-话-滚动吸附-松手即停稳" aria-label="Permalink to &quot;漫画 · 第 35 话 滚动吸附：松手即停稳&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/23-scroll-snap">docs/css/23-scroll-snap.md</a> ｜ 原画：<a href="./EP.35-scroll-snap.svg">EP.35-scroll-snap.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。轮播图 scroll 事件 + debounce + <code>scrollTo</code> 手动校正落点，移动端还得引 swiper 库模拟触摸惯性，低端机卡成 PPT。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 Scroll Snap 双件套——容器 <code>scroll-snap-type</code> 定方向与严格度，子项 <code>scroll-snap-align</code> 给吸附点，浏览器原生接管。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被「滚动停在两张图中间」折磨：JS 监听 scroll 算落点，手感永远差一口气；快速甩动一滑到底，固定头还把落点内容挡住。标签君引入 Scroll Snap——<code>mandatory</code> 强制吸附、<code>proximity</code> 就近轻吸、<code>stop: always</code> 逐项停靠、<code>scroll-padding</code> 收缩吸附口避让固定头。像素酱发现连轮播圆点导航都能用锚点零 JS 完成。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>传统方案命令式校正：scroll 事件里 debounce，算最近卡片位置再 <code>scrollTo</code>。叠加痛苦：停在两张图中间、一甩跳过三张、固定头遮落点、低端机掉帧、JS 禁用完全失效。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>容器 <code>scroll-snap-type: x mandatory</code> 声明方向与严格度，子项 <code>scroll-snap-align: center</code> 声明吸附点。滚动结束浏览器自动算最近落点并平滑吸附；<code>scroll-snap-stop: always</code> 让快速甩动也逐项停靠。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：水平卡片流（首尾靠 <code>scroll-padding-inline</code> 居中）、整屏翻页（<code>stop: always</code> 不连跳）、纯 CSS 轮播（锚点 + smooth）、mandatory 与 proximity 的分寸。记住边界：<strong>内容不定高时用 proximity</strong>，否则高过一屏的内容会被「锁死」滚不到。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>容器 scroll-snap-type 定方向与严格度，子项 scroll-snap-align 给吸附点。</li><li>mandatory 强制吸附；内容不定高时用 proximity，否则中间内容滚不到。</li><li>固定头遮落点：容器补 scroll-padding-top，scrollIntoView 同样生效。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 <code>y mandatory</code> 的整屏翻页里，某一屏内容超过 100vh 会出问题？</p><p><strong>答</strong>：mandatory 要求滚动结束必须吸附到某个吸附点。内容高过一屏时，中间部分距离任何吸附点都太远，浏览器会把它「吸回」最近吸附点——中间内容永远无法停留阅读。解法：改用 <code>proximity</code>，或只给屏首标题设吸附点。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>卡片流 + 整屏翻页 + 纯 CSS 轮播 + mandatory/proximity 对比 + scroll-padding 避让：<a href="./../../examples/css/23-scroll-snap/index-01-scroll-snap.html">examples/css/23-scroll-snap/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 36 话《dialog 元素》——<code>showModal()</code> 一句进入 top layer：页面自动惰性化、焦点圈禁、Esc 关闭、<code>::backdrop</code> 定制遮罩，弹窗三件套零依赖完成。</p>',22)])])}const u=o(s,[["render",c]]);export{m as __pageData,u as default};
